typedef unsigned int uint32;

struct string_buf;
class stringx
{
    char* chars;
    string_buf* my_buf;
public:
    stringx(const stringx&);
    ~stringx();
    stringx& operator=(const stringx&);
};

class matrix4x4
{
    float values[16] __attribute__((aligned(16)));
};

class vector3d
{
public:
    float x;
    float y;
    float z;
};

class PanelGeom
{
public:
    stringx name;
    stringx properties;
    matrix4x4 matrix;
    vector3d boundboxcenter;
    vector3d boundboxsize;
    uint32 nchildren;
    PanelGeom* children;
    PanelGeom* next;
    PanelGeom* parent;

    virtual ~PanelGeom();
    virtual int Kind() const = 0;
    virtual bool Load(unsigned char* buffer, int& index);
    static PanelGeom* LoadGeom(unsigned char* buffer, int& index);
};

uint32 ReadLong(unsigned char* buffer, int& index);
stringx ReadString(unsigned char* buffer, int& index);
void ReadMatrix3x4(matrix4x4& m, unsigned char* buffer, int& index);
void ReadVector3d(vector3d& v, unsigned char* buffer, int& index);

bool PanelGeom::Load(unsigned char* buffer, int& index)
{
	name = ReadString(buffer, index);
	stringx junkstringx = ReadString(buffer, index);
	ReadMatrix3x4(matrix, buffer, index);
	ReadVector3d(boundboxcenter, buffer, index);
	ReadVector3d(boundboxsize, buffer, index);
	nchildren = ReadLong(buffer, index);
	for(int i=nchildren; --i >=0; )
	{
		PanelGeom* geom = PanelGeom::LoadGeom(buffer, index);
		if(!geom) return false;

		geom->parent = this;
		geom->next = children;
		children = geom;
	}
	return true;
}
